CREATE TABLE IF NOT EXISTS users(id INT AUTO_INCREMENT PRIMARY KEY,name VARCHAR(100),username VARCHAR(100) UNIQUE,password VARCHAR(255));
CREATE TABLE IF NOT EXISTS profiles(id INT AUTO_INCREMENT PRIMARY KEY,name VARCHAR(150) NOT NULL,class_name VARCHAR(150),tagline VARCHAR(255),bio TEXT,main_skills VARCHAR(255),birth_info VARCHAR(150),address VARCHAR(255),interests VARCHAR(255),goal TEXT,email VARCHAR(150),phone VARCHAR(50),github VARCHAR(255),instagram VARCHAR(255),linkedin VARCHAR(255),photo VARCHAR(255));
CREATE TABLE IF NOT EXISTS educations(id INT AUTO_INCREMENT PRIMARY KEY,school VARCHAR(200) NOT NULL,period VARCHAR(80),description TEXT);
CREATE TABLE IF NOT EXISTS skills(id INT AUTO_INCREMENT PRIMARY KEY,name VARCHAR(100) NOT NULL,type ENUM('hard','soft') DEFAULT 'hard',percent TINYINT UNSIGNED NOT NULL);
CREATE TABLE IF NOT EXISTS projects(id INT AUTO_INCREMENT PRIMARY KEY,name VARCHAR(200) NOT NULL,category VARCHAR(100),description TEXT,problem TEXT,goal TEXT,tech VARCHAR(255),role VARCHAR(150),features TEXT,demo_url VARCHAR(255),github_url VARCHAR(255),documentation TEXT,detail TEXT,feedback TEXT,image VARCHAR(255),created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS certificates(id INT AUTO_INCREMENT PRIMARY KEY,title VARCHAR(200) NOT NULL,year VARCHAR(10),description TEXT,image VARCHAR(255));
CREATE TABLE IF NOT EXISTS experiences(id INT AUTO_INCREMENT PRIMARY KEY,title VARCHAR(200) NOT NULL,type ENUM('plk','organisasi','lomba') DEFAULT 'plk',place VARCHAR(200),period VARCHAR(80),description TEXT,image VARCHAR(255));
CREATE TABLE IF NOT EXISTS testimonials(id INT AUTO_INCREMENT PRIMARY KEY,name VARCHAR(100) NOT NULL,role ENUM('guru','teman','pengguna','plk') DEFAULT 'teman',content TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS messages(id INT AUTO_INCREMENT PRIMARY KEY,name VARCHAR(100) NOT NULL,category VARCHAR(50),body TEXT NOT NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS blog_posts(id INT AUTO_INCREMENT PRIMARY KEY,title VARCHAR(200) NOT NULL,excerpt VARCHAR(300),content LONGTEXT,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
